import java.util.*;
import java.util.regex.*;

public class Main {
    public static void main(String[] args) {
        String text = new Scanner(System.in).nextLine().strip();
        Matcher m = Pattern.compile("(\\d{4})-(\\d{2})-(\\d{2})").matcher(text);
        if (m.matches()) {
            System.out.println("y=" + m.group(1) + " m=" + m.group(2) + " d=" + m.group(3));
        } else {
            System.out.println("invalid");
        }
    }
}

